	// write header
	void FreeCAD::write_header(const std::string &model_name){
		// import needed libraries
		fid_<<"# Generated by RAT "<<
			Extra::create_version_tag(
			CMN_PROJECT_VER_MAJOR,
			CMN_PROJECT_VER_MINOR,
			CMN_PROJECT_VER_PATCH)<<"\n";
		fid_<<"\n";

		fid_<<"# import libraries\n";
		fid_<<"import FreeCAD,Draft,Part,Import,math\n";
		fid_<<"\n";

		// check version
		fid_<<"# need at least FreeCAD version 1.0.0\n";
		fid_<<"major, minor, revision, *_ = FreeCAD.Version()\n";
		fid_<<"if int(major) < 1:\n";
		fid_<<"\traise RuntimeError(f'FreeCAD version {major}.{minor}.{revision} is too old, need >= 1.0.0'.format(major, minor, revision))\n";
		fid_<<"\n";

		// create a new document
		fid_<<"# create a new document\n";
		fid_<<"doc = App.newDocument(\""<<model_name<<"\")\n";

		// turn unecessary features off
		fid_<<"doc.UndoMode = 0\n"; // faster build speed
		fid_<<"\n";

		// storage arrays
		fid_<<"# arrays for storing objects\n";
		fid_<<"export=[]\n"; // parts to write to the output file
		fid_<<"parts=[]\n"; // parts to combine into a compound or multifuse
		fid_<<"lines=[]\n"; // lines to combine into a multiline
		fid_<<"group=[]\n"; // tree structure
		fid_<<"features=[]\n"; // features to clean when showing gui output
		fid_<<"\n";

		// set view to 3D
		fid_<<"# set camera 3D view\n";
		fid_<<"if FreeCAD.GuiUp:\n";
		fid_<<"\tFreeCADGui.ActiveDocument.ActiveView.viewDefaultOrientation('Trimetric', 0)\n";
		fid_<<"\tFreeCADGui.updateGui()\n";
		fid_<<"\n";
	}

	// append group
	void FreeCAD::append_group(const std::string &group_name){
		// add the group to the list
		fid_<<"# add folder to document\n";
		fid_<<"if len(group) == 0:\n";
		fid_<<"\tgr = doc.addObject(\"App::DocumentObjectGroup\",\""<<group_name<<"\")\n";
		fid_<<"\tgroup.append(gr)\n";
		fid_<<"else:\n";
		fid_<<"\tgr = doc.addObject(\"App::DocumentObjectGroup\",\""<<group_name<<"\")\n";
		fid_<<"\tgroup[-1].addObject(gr)\n";
		fid_<<"\tgroup.append(gr)\n";
		fid_<<"\n";
	}

	// pop group
	void FreeCAD::pop_group(){
		fid_<<"# folder complete\n";
		fid_<<"group.pop()\n";
		fid_<<"\n";
	}

	// write edges
	void FreeCAD::write_edges( 
		const arma::field<arma::Mat<fltp> > &x,
		const arma::field<arma::Mat<fltp> > &y, 
		const arma::field<arma::Mat<fltp> > &z,
		const arma::Row<arma::uword> &section_idx,
		const arma::Row<arma::uword> &turn_idx,
		const std::string &coil_name, 
		const arma::Col<fltp>::fixed<3>& color){

		// check for empty
		if(x.is_empty() || y.is_empty() || z.is_empty())return;

		// create group with same name as coil
		// fid_<<"gr = doc.addObject(\"App::DocumentObjectGroup\",\""<<coil_name<<"\")\n";
		// fid_<<"gr = doc.addObject('App::Part','"<<coil_name<<"')\n";

		// avoid same names
		const arma::uword cnt = ++coil_name_count_[coil_name];
		std::string coil_name_ext = coil_name;
		if(cnt>1)coil_name_ext += "_" + std::to_string(cnt);

		// for gui
		if(enable_gui_update_){
			// setup bounding box
			setup_bounding_box(x,y,z);

			// fit view
			fid_<<"# fit all geometry to viewport\n";
			fid_<<"if FreeCAD.GuiUp:\n";
			fid_<<"\tFreeCADGui.ActiveDocument.ActiveView.fitAll()\n";
			fid_<<"\n";
		}

		// walk over sections
		for(arma::uword i=0;i<x.n_elem;i++){
			// // write section
			// const fltp angular_tolerance = arma::Datum<fltp>::pi/180/10;
			
			// check if closed
			// const bool closed = is_closed(x(i),y(i),z(i),1e-9);

			// header
			fid_<<"# section "<<section_idx(i)<<", turn "<<turn_idx(i)<<"\n";

			// single edge (i.e. a line)
			if(x(i).n_rows==1){
				write_using_ruled_surfaces(x(i),y(i),z(i),color);
			}

			// surface mesh with 2 edges
			else if(x(i).n_rows==2){
				if(override_cross_sections_){
					write_using_generators(x(i),y(i),z(i),color); // this is technically the same as making cross sections
				// }else if(override_ruled_surface_ && 
				// 	is_ruled_surface(x(i),y(i),z(i),0,1,angular_tolerance)){
				}else if(override_ruled_surface_){
					write_using_ruled_surfaces(x(i),y(i),z(i),color);
				}else{
					write_using_generators(x(i),y(i),z(i),color);
				}
			}

			// volume mesh with four edges
			else if(x(i).n_rows==4){
				if(override_cross_sections_){
					write_using_cross_sections(x(i),y(i),z(i),color);
				// }else if(!closed && override_ruled_surface_){
				// }else if(override_ruled_surface_ && (
				// 	is_ruled_surface(x(i),y(i),z(i),0,1,angular_tolerance) && 
				// 	is_ruled_surface(x(i),y(i),z(i),2,3,angular_tolerance))){
				}else if(override_ruled_surface_){
					write_using_ruled_surfaces(x(i),y(i),z(i),color);
				}else{
					write_using_generators(x(i),y(i),z(i),color);
				}
			}

			// 3 edges or more than 4 edges must try to use loft method
			else{
				// only option
				write_using_cross_sections(x(i),y(i),z(i),color);
			}

			// section done
			fid_<<"\n";
		}

		// unify
		group_parts(coil_name, color);

		// clean the bounding box
		if(enable_gui_update_)clean_bounding_box();
		
		// fit all 
		fid_<<"if FreeCAD.GuiUp:\n";
		if(!enable_gui_update_)fid_<<"\tFreeCADGui.ActiveDocument.ActiveView.fitAll()\n";
		fid_<<"\tFreeCADGui.updateGui()\n";
		fid_<<"\n";
	}

	// export the geometry
	// by connecting edges with ruled surface
	// then use loft to connect the two ruled surfaces
	// only works with 1,2 or 4 edges. Also this method,
	// due to the use of a ruled surface, assumes that 
	// all generator lines are perpendicular to the edges
	// of the cable. It is therefore not a good choice for
	// frenet-serret frame.
	void FreeCAD::write_using_ruled_surfaces(
		const arma::Mat<fltp> &x,
		const arma::Mat<fltp> &y, 
		const arma::Mat<fltp> &z,
		const arma::Col<fltp>::fixed<3>& color){

		// check for empty
		assert(!x.is_empty());
		assert(!y.is_empty());
		assert(!z.is_empty());
		assert(x.n_rows==1 || x.n_rows==2 || x.n_rows==4);
		assert(y.n_rows==x.n_rows);
		assert(z.n_rows==x.n_rows);

		// get number of edges
		const arma::uword num_edges = x.n_rows;
		const arma::uword num_coords = x.n_cols;

		// header
		fid_<<"# using ruled surfaces method\n";

		// check if closed
		const bool closed = is_closed(x,y,z,1e-9);

		// get number of points used for setting up geometry
		// const arma::uword num_points = num_coords; 
		const arma::uword num_points = num_coords-int(closed); 

		// walk over edges
		for(arma::uword k=0;k<num_edges;k++){
			// straight line
			if(is_straight(arma::join_vert(x.row(k),y.row(k),z.row(k)))){
				// sanity check
				if(closed)rat_throw_line("a straight line can not be closed");

				// indices of points
				const arma::uword idx0 = 0, idx1 = num_points-1;

				// create points
				fid_<<"p0 = FreeCAD.Vector("<<scale_*x(k,idx0)<<","<<scale_*y(k,idx0)<<","<<scale_*z(k,idx0)<<")\n";
				fid_<<"p1 = FreeCAD.Vector("<<scale_*x(k,idx1)<<","<<scale_*y(k,idx1)<<","<<scale_*z(k,idx1)<<")\n";
				
				// create vertices
				fid_<<"vtx0 = Part.Vertex(p0)\n";
				fid_<<"vtx1 = Part.Vertex(p1)\n";

				// gui output
				if(enable_gui_update_){
					// show vertices
					create_feature("vtx0", color);
					create_feature("vtx1", color);

					// update the GUI
					trigger_gui_update();
				}

				// create a straight line
				fid_<<"crv = Part.LineSegment(p0,p1,Parameters=["<<idx0<<","<<idx1<<"])\n";

				// create the splines themselves
				fid_<<"spline"<<k<<" = crv.toShape()\n";

				// gui output
				if(enable_gui_update_){
					// show the line in the GUI
					create_feature("spline" + std::to_string(k), color);

					// remove vertices
					remove_feature("vtx0");
					remove_feature("vtx1");

					// update the GUI
					trigger_gui_update();
				}
			}

			// arc or perhaps full circle
			else if(is_arc(arma::join_vert(x.row(k),y.row(k),z.row(k)))){
				// indices of points
				const arma::uword idx0 = 0, idx1 = num_points/2, idx2 = num_points-1;

				// create points
				fid_<<"p0 = FreeCAD.Vector("<<scale_*x(k,idx0)<<","<<scale_*y(k,idx0)<<","<<scale_*z(k,idx0)<<")\n";
				fid_<<"p1 = FreeCAD.Vector("<<scale_*x(k,idx1)<<","<<scale_*y(k,idx1)<<","<<scale_*z(k,idx1)<<")\n";
				fid_<<"p2 = FreeCAD.Vector("<<scale_*x(k,idx2)<<","<<scale_*y(k,idx2)<<","<<scale_*z(k,idx2)<<")\n";

				// create vertices
				fid_<<"vtx0 = Part.Vertex(p0)\n";
				fid_<<"vtx1 = Part.Vertex(p1)\n";
				fid_<<"vtx2 = Part.Vertex(p2)\n";

				// gui output
				if(enable_gui_update_){
					// show vertices
					create_feature("vtx0", color);
					create_feature("vtx1", color);
					create_feature("vtx2", color);

					// update the GUI
					trigger_gui_update();
				}

				// create arc
				fid_<<"crv = Part.Arc(p0,p1,p2,Parameters=["<<idx0<<","<<idx1<<","<<idx2<<"])\n";
				
				// build full circle if the path was closed
				if(closed){
					fid_<<"# circle extraction\n";
					fid_<<"edge = crv.toShape().Edges[0]\n";
					fid_<<"crv = edge.Curve\n";
				}

				// create the splines themselves
				fid_<<"spline"<<k<<" = crv.toShape()\n";

				// gui output
				if(enable_gui_update_){
					// show the line in the GUI
					create_feature("spline" + std::to_string(k), color);

					// remove vertices
					remove_feature("vtx0");
					remove_feature("vtx1");
					remove_feature("vtx2");

					// update the GUI
					trigger_gui_update();
				}
			}

			// something more complicated
			else{
				// create params that aligns edges
				fid_<<"params = [k for k in range("<<num_coords<<")]\n"; // this should have a closing value

				// walk over coordinates
				for(arma::uword j=0;j<num_coords;j++){
					// create coordinate
					fid_<<"p"<<j<<" = FreeCAD.Vector(";
					fid_<<scale_*x(k,j)<<","<<scale_*y(k,j)<<","<<scale_*z(k,j);
					fid_<<")\n";

					// gui output
					if(enable_gui_update_){
						// create a vertex to show the coordinate
						fid_<<"vtx"<<j<<" = Part.Vertex(p"<<j<<")\n";

						// show the line in the GUI
						create_feature("vtx" + std::to_string(j), color);

						// update the GUI
						trigger_gui_update();
					}
				}

				// create single spline
				fid_<<"crv = Part.BSplineCurve()\n";
				if(spline_tolerance_>0){
					fid_<<"crv.approximate([";
				}else{
					fid_<<"crv.interpolate([";
				}
				for(arma::uword j=0;j<num_coords;j++){
					fid_<<"p"<<j;
					if(j!=num_coords-1)fid_<<",";
				}
				if(spline_tolerance_>0){
					fid_<<"], Tolerance="<<scale_*spline_tolerance_<<", Parameters=params)\n";
				}else{
					fid_<<"], Parameters=params, PeriodicFlag="<<(false ? "True" : "False")<<")\n";
				}

				// create the splines themselves
				fid_<<"spline"<<k<<" = crv.toShape()\n";
				// fid_<<"spline"<<k<<" = Part.Wire([spline"<<k<<"])\n";

				// gui output
				if(enable_gui_update_){
					// show the line in the GUI
					create_feature("spline" + std::to_string(k), color);

					// remove vertices
					for(arma::uword j=0;j<num_coords;j++)
						remove_feature("vtx" + std::to_string(j));

					// update the GUI
					trigger_gui_update();
				}
			}
		}

		// single edge
		if(num_edges==1){
			// add to lines 
			fid_<<"lines.append(spline0)\n";
		}

		// is at least surface
		else if(num_edges==2){
			// check if surface 0-1 is planar
			const bool planar01 = is_planar(arma::join_horiz(
				arma::join_vert(x.row(0),y.row(0),z.row(0)), 
				arma::join_vert(x.row(1),y.row(1),z.row(1))));

			// when the two curves are planar and closed the loft fails
			if(planar01 && closed){
				fid_<<"rule0 = Part.makeRuledSurface(spline0, spline1)\n";
			}else{
				fid_<<"rule0 = Part.makeLoft([spline0,spline1], solid=False, ruled=True, closed=False)\n";
			}

			// gui output
			if(enable_gui_update_){
				// show the surface in the GUI
				create_feature("rule0", color);

				// no longer show lines
				remove_feature("spline0");
				remove_feature("spline1");

				// update the GUI
				trigger_gui_update();
			}

			// add object to group
			fid_<<"parts.append(rule0)\n";
		}

		// is volume mesh
		else if(num_edges==4){
			// check if surfaces are planar
			const bool planar01 = is_planar(arma::join_horiz(
				arma::join_vert(x.row(0),y.row(0),z.row(0)), 
				arma::join_vert(x.row(1),y.row(1),z.row(1))));
			const bool planar32 = is_planar(arma::join_horiz(
				arma::join_vert(x.row(3),y.row(3),z.row(3)), 
				arma::join_vert(x.row(2),y.row(2),z.row(2))));

			// when the two curves are planar and closed the loft fails
			if(planar01 && closed){
				fid_<<"rule0 = Part.makeRuledSurface(spline0, spline1)\n";
			}else{
				fid_<<"rule0 = Part.makeLoft([spline0,spline1], solid=False, ruled=True, closed=False)\n";
			}

			// gui output
			if(enable_gui_update_){
				// show the surface in the GUI
				create_feature("rule0", color);

				// no longer show lines
				remove_feature("spline0");
				remove_feature("spline1");

				// update the GUI
				trigger_gui_update();
			}

			// when the two curves are planar and closed the loft fails
			if(planar32 && closed){
				fid_<<"rule1 = Part.makeRuledSurface(spline3, spline2)\n";
			}else{
				fid_<<"rule1 = Part.makeLoft([spline3,spline2], solid=False, ruled=True, closed=False)\n";
			}

			// gui output
			if(enable_gui_update_){
				// show the surface in the GUI
				create_feature("rule1", color);

				// no longer show lines
				remove_feature("spline2");
				remove_feature("spline3");

				// update the GUI
				trigger_gui_update();
			}

			// create a loft
			fid_<<"loft = Part.makeLoft([rule0,rule1], solid=True, ruled=True, closed=False)\n";
			
			// gui output
			if(enable_gui_update_){
				// show the surface in the GUI
				create_feature("loft", color);

				// no longer show lines
				remove_feature("rule0");
				remove_feature("rule1");

				// update the GUI
				trigger_gui_update();
			}

			// add to parts
			fid_<<"parts.append(loft)\n";
		}
	}


	// export the geometry by drawing first 
	// the cross sections then connecting the
	// cross sections with a loft 
	// this method can deal with any number of 
	// edges. It does try to determine whether
	// an edge is a sharp corner or not by checking
	// its angle
	void FreeCAD::write_using_cross_sections(
		const arma::Mat<fltp> &x,
		const arma::Mat<fltp> &y, 
		const arma::Mat<fltp> &z,
		const arma::Col<fltp>::fixed<3>& color){

		// check for empty
		assert(!x.is_empty());
		assert(!y.is_empty());
		assert(!z.is_empty());
		assert(y.n_rows==x.n_rows);
		assert(z.n_rows==x.n_rows);

		// settings
		const fltp angle_treshold = RAT_CONST(40.0)*arma::Datum<fltp>::tau/RAT_CONST(360.0);
		const fltp drop_treshold = arma::Datum<fltp>::pi/180/100;

		// header
		fid_<<"# cross section loft method\n";

		// check closed
		const bool closed = is_closed(x,y,z,1e-9);

		// get number of edges
		const arma::uword num_edges = x.n_rows;
		const arma::uword num_coords = x.n_cols;

		// walk over profiles
		for(arma::uword j=0;j<num_coords-int(closed);j++){
			// calculate angles between consecutive elements
			arma::Mat<fltp> R = arma::join_horiz(x.col(j),y.col(j),z.col(j)).t();
			R = arma::join_horiz(R,R.col(0)); // duplicate first point at end to create circular loop
			arma::Mat<fltp> dR = arma::diff(R,1,1); // calculate derivative to create edges
			dR = arma::join_horiz(dR.tail_cols(1),dR); // duplicate last edge at start to create loop
			dR.each_row()/=Extra::vec_norm(dR); // normalize edge vectors

			// calculate angles at nodes
			const arma::Row<fltp> alpha = Extra::vec_angle(dR.head_cols(num_edges),dR.tail_cols(num_edges));

			// find corner points
			arma::Row<arma::uword> mark_corner = arma::abs(alpha)>angle_treshold;

			// find points that are actualy just straight
			arma::Row<arma::uword> drop_points = arma::abs(alpha)<drop_treshold;

			// find corners or points that are next to a series of consecutive 
			// drop points these are start/end points but not drop points themselves
			mark_corner = (mark_corner + arma::shift(drop_points,1,1) + drop_points + arma::shift(drop_points,-1,1))>0 && drop_points==0;

			// do not drop corners ever
			drop_points = drop_points && mark_corner==false;

			// find corner indices
			const arma::Col<arma::uword> idx_corner = arma::find(mark_corner);

			// no corners it is a closed spline
			arma::uword num_splines = 0;
			if(idx_corner.is_empty()){
				// we're using all vertices
				for(arma::uword k=0;k<num_edges;k++){
					// create points
					fid_<<"p"<<k<<" = FreeCAD.Vector(";
					fid_<<scale_*x(k,j)<<","<<scale_*y(k,j)<<","<<scale_*z(k,j);
					fid_<<")\n";

					// gui output
					if(enable_gui_update_){
						// create a vertex to show the coordinate
						fid_<<"vtx"<<k<<" = Part.Vertex(p"<<k<<")\n";

						// show the line in the GUI
						create_feature("vtx" + std::to_string(k), color);

						// update the GUI
						trigger_gui_update();
					}
				}

				// create params that aligns edges
				fid_<<"params = [k for k in range("<<num_edges<<")]\n";

				// create single spline
				fid_<<"crv = Part.BSplineCurve()\n";
				if(spline_tolerance_>0){
					fid_<<"crv.approximate([";
				}else{
					fid_<<"crv.interpolate([";
				}
				for(arma::uword k=0;k<num_edges;k++){
					fid_<<"p"<<k;
					if(k!=num_edges-1)fid_<<",";
				}
				if(spline_tolerance_>0){
					fid_<<"], Tolerance="<<scale_*spline_tolerance_<<", Parameters=params)\n";
				}else{
					fid_<<"], Parameters=params)\n";
				}
				fid_<<"crv.setPeriodic()\n";
				fid_<<"spline0 = crv.toShape()\n";
				num_splines = 1;

				// gui output
				if(enable_gui_update_){
					// show the line in the GUI
					create_feature("spline0", color);

					// remove vertices
					for(arma::uword k=0;k<num_edges;k++)
						remove_feature("vtx" + std::to_string(k));

					// update the GUI
					trigger_gui_update();
				}
			}

			// open spline
			else{
				// were using only non-dropped vertices
				for(arma::uword k=0;k<num_edges;k++){
					// check if point was dropped
					if(drop_points(k))continue;

					// create points
					fid_<<"p"<<k<<" = FreeCAD.Vector(";
					fid_<<scale_*x(k,j)<<","<<scale_*y(k,j)<<","<<scale_*z(k,j);
					fid_<<")\n";

					// gui output
					if(enable_gui_update_){
						// create a vertex to show the coordinate
						fid_<<"vtx"<<k<<" = Part.Vertex(p"<<k<<")\n";

						// show the line in the GUI
						create_feature("vtx" + std::to_string(k), color);

						// update the GUI
						trigger_gui_update();
					}
				}

				// walk over sections
				num_splines = idx_corner.n_elem;
				for(arma::uword k=0;k<num_splines;k++){
					// get looping indices
					const arma::uword idx1 = idx_corner(k);
					const arma::uword idx2 = idx_corner((k+1)%idx_corner.n_elem);

					// more than two points use smooth spline
					if(idx2 - idx1 + 1>2){
						// check if all points between idx1 and idx2 are dropped
						bool is_straight_line = true;
						for(arma::uword l=idx1;l!=idx2;l++){
							if(l==drop_points.n_elem)l=0;
							if(drop_points(l)==false){
								is_straight_line=false; break;
							}
						}

						// all points in between were dropped its a straight line segment
						if(is_straight_line){
							// connect points with line
							fid_<<"spline"<<k<<" = Part.LineSegment(p"<<idx1<<", p"<<idx2<<").toShape()\n";
						}

						// more than 2 points
						else{
							// create params that aligns edges
							fid_<<"params=[";
							arma::uword num_points = 0;
							for(arma::uword l=idx1;;l++){
								if(l>=num_edges)l=0;
								if(drop_points(l))continue;
								fid_<<l;
								num_points++;
								if(l==idx2)break;
								fid_<<",";
							}
							fid_<<"]\n";

							if(num_points==2){
								fid_<<"spline"<<k<<" = Part.LineSegment(p"<<idx1<<", p"<<idx2<<").toShape()\n";
							}

							else{
								// create a smooth spline
								fid_<<"crv = Part.BSplineCurve()\n";
								if(spline_tolerance_>0){
									fid_<<"crv.approximate([";
								}else{
									fid_<<"crv.interpolate([";
								}
								for(arma::uword l=idx1;;l++){
									if(l>=num_edges)l=0;
									if(drop_points(l))continue;
									fid_<<"p"<<l;
									if(l==idx2)break;
									fid_<<",";
								}
								if(spline_tolerance_>0){
									fid_<<"], Tolerance="<<scale_*spline_tolerance_<<", Parameters=params)\n";
								}else{
									fid_<<"], Parameters=params)\n";
								}
								fid_<<"spline"<<k<<" = crv.toShape()\n";
							}

						}
					}

					// two points create straight line
					else{
						// connect points with line
						fid_<<"spline"<<k<<" = Part.LineSegment(p"<<idx1<<", p"<<idx2<<").toShape()\n";
					}
				}

				// gui output
				if(enable_gui_update_){
					// show the line in the GUI
					for(arma::uword k=0;k<num_splines;k++)
						create_feature("spline" + std::to_string(k), color);

					// remove vertices
					for(arma::uword k=0;k<num_edges;k++){
						if(drop_points(k))continue;
						remove_feature("vtx" + std::to_string(k));
					}

					// update the gui
					trigger_gui_update();
				}
			}

			// create wire
			fid_<<"wire=Part.Wire(Part.__sortEdges__([";
			for(arma::uword i=0;i<num_splines;i++){
				fid_<<"spline"<<i;
				if(i!=num_splines-1)fid_<<",";
			}
			fid_<<"]))\n";

			// create face between splines
			fid_<<"face"<<j<<" = Part.Face(wire)\n";

			// gui output
			if(enable_gui_update_){
				// show the face in the GUI
				create_feature("face" + std::to_string(j), color);

				// remove vertices
				for(arma::uword i=0;i<num_splines;i++)
					remove_feature("spline" + std::to_string(i));

				// update the gui
				trigger_gui_update();
			}
		}

		// // create guide wire
		// fid_<<"# guide wire\n";
		// for(arma::uword j=0;j<num_coords-int(closed);j++){
		// 	fid_<<"p"<<j<<" = FreeCAD.Vector(";
		// 	fid_<<scale_*x(0,j)<<","<<scale_*y(0,j)<<","<<scale_*z(0,j);
		// 	fid_<<")\n";
		// }
		// fid_<<"params = [k for k in range("<<num_coords<<")]\n"; // this should have a closing value
		// fid_<<"crv = Part.BSplineCurve()\n";
		// fid_<<"crv.interpolate([";
		// for(arma::uword j=0;j<num_coords;j++){
		// 	fid_<<"p"<<j;
		// 	if(j!=num_coords-1)fid_<<",";
		// }
		// fid_<<"], Parameters=params, PeriodicFlag="<<(false ? "True" : "False")<<")\n";
		// fid_<<"guide = crv.toShape()\n";

		// // show the guide in the GUI
		// if(enable_gui_update_){
		// 	create_feature("guide", color);

		// 	// update the gui
		// 	trigger_gui_update();
		// }

		// create a loft
		fid_<<"loft=Part.makeLoft([";
		for(arma::uword j=0;j<num_coords-int(closed);j++){
			fid_<<"face"<<j;
			if(j!=num_coords-int(closed)-1)fid_<<",";
		}
		fid_<<"], solid=True, ruled=False, closed="<<(closed ? "True" : "False")<<")\n";
		// not ruled here as it makes only sense for 2 edges

		// remove splitters
		if(closed)fid_<<"loft.removeSplitter()\n";

		// add object to group
		fid_<<"parts.append(loft)\n";

		// gui output
		if(enable_gui_update_){
			// show the loft in the GUI
			create_feature("loft", color);

			// show the line in the GUI
			for(arma::uword j=0;j<num_coords-int(closed);j++)
				remove_feature("face" + std::to_string(j));

			// // remove the guide
			// remove_feature("guide");

			// update the gui
			trigger_gui_update();
		}
	}

	// export the geometry by drawing the generator lines
	// then connecting them with a surface. IN contrast to 
	// the first method the lines can have an angle with
	// respect to the edges. Therefore it works also for
	// Frenet-Serret frame. But somehow this method
	// is a bit more unstable to use.
	void FreeCAD::write_using_generators(
		const arma::Mat<fltp> &x,
		const arma::Mat<fltp> &y, 
		const arma::Mat<fltp> &z,
		const arma::Col<fltp>::fixed<3>& color){

		// check for empty
		assert(!x.is_empty());
		assert(!y.is_empty());
		assert(!z.is_empty());
		assert(x.n_rows==2 || x.n_rows==4);
		assert(y.n_rows==x.n_rows);
		assert(z.n_rows==x.n_rows);
		assert(y.n_cols==x.n_cols);
		assert(z.n_cols==x.n_cols);

		// header
		fid_<<"# generator line method\n";

		// check if closed
		// const bool closed = is_closed(x,y,z,1e-9);

		// get number of edges
		const arma::uword num_edges = x.n_rows;
		const arma::uword num_coords = x.n_cols;

		// walk over surfaces
		for(arma::uword j=0;j<num_edges/2;j++){
			// indices
			const arma::uword idx1 = num_edges==2 ? 0 : (j==0 ? 1 : 3);
			const arma::uword idx2 = num_edges==2 ? 1 : (j==0 ? 2 : 0);

			// first side
			for(arma::uword k=0;k<num_coords;k++){
				// first point
				fid_<<"p1"<<"=FreeCAD.Vector(";
				fid_<<scale_*x(idx1,k)<<","<<scale_*y(idx1,k)<<","<<scale_*z(idx1,k);
				fid_<<")\n";

				// gui output
				if(enable_gui_update_){
					// create a vertex to show the coordinate
					fid_<<"vtx1 = Part.Vertex(p1)\n";

					// show the line in the GUI
					create_feature("vtx1", color);

					// update the GUI
					trigger_gui_update();
				}

				// second point
				fid_<<"p2"<<"=FreeCAD.Vector(";
				fid_<<scale_*x(idx2,k)<<","<<scale_*y(idx2,k)<<","<<scale_*z(idx2,k);
				fid_<<")\n";

				// gui output
				if(enable_gui_update_){
					// create a vertex to show the coordinate
					fid_<<"vtx2 = Part.Vertex(p2)\n";

					// show the line in the GUI
					create_feature("vtx2", color);

					// update the GUI
					trigger_gui_update();
				}

				// connect points with line
				// fid_<<"line"<<k<<"=Draft.make_line(p1,p2)\n";
				fid_<<"line"<<k<<"=Part.LineSegment(p1, p2).toShape()\n";

				// gui output
				if(enable_gui_update_){
					// show the line in the GUI
					create_feature("line" + std::to_string(k), color);

					// delete vertices
					remove_feature("vtx1");
					remove_feature("vtx2");

					// update the GUI
					trigger_gui_update();
				}
			}

			// create a loft from the generator lines
			// TODO need investigate if we can use internal Parameters here
			// maybe by making this from a point grid instead 
			// of a series of lines
			fid_<<"surf"<<j<<" = Part.makeLoft([";
			for(arma::uword k=0;k<num_coords;k++){
				fid_<<"line"<<k;
				if(k!=num_coords-1)fid_<<",";
			}
			fid_<<"], solid=False, ruled=False, closed="<<(false ? "True" : "False")<<")\n";

			// gui output
			if(enable_gui_update_){
				// show the surface in the GUI
				create_feature("surf" + std::to_string(j), color);

				// no longer show lines
				for(arma::uword k=0;k<num_coords;k++)
					remove_feature("line" + std::to_string(k)); // clean lines

				// update the GUI
				trigger_gui_update();
			}
		}

		// surface
		if(num_edges==2){
			fid_<<"parts.append(surf0)\n";
		}

		// volume
		else if(num_edges==4){
			// create loft
			fid_<<"loft = Part.makeLoft([surf0,surf1], solid=True, ruled=True, closed=False)\n";

			// gui output
			if(enable_gui_update_){
				// show the loft in the GUI
				create_feature("loft", color);

				// no longer show surfaces
				for(arma::uword j=0;j<num_edges/2;j++)
					remove_feature("surf" + std::to_string(j)); 

				// update the GUI
				trigger_gui_update();
			}

			// add to parts
			fid_<<"parts.append(loft)\n";
		}

		// other
		else rat_throw_line("num edges must be 2 or 4 for this method");

		
	}

	// create union
	void FreeCAD::group_parts(const std::string& coil_name, const arma::Col<fltp>::fixed<3>& color){
		// header
		fid_<<"# performing fuse/compound on "<<coil_name<<"\n";

		// join lines
		fid_<<"if len(lines)!=0:\n";
		fid_<<"\twire = Part.Wire(Part.__sortEdges__(lines))\n";

		// create feature
		fid_<<"\tcoil = doc.addObject('Part::Feature','"<<coil_name<<"')\n";
		fid_<<"\tcoil.Shape = wire\n";

		// wire color
		fid_<<"\tif FreeCAD.GuiUp:\n";
		fid_<<"\t\tcoil.ViewObject.LineColor = (1.0,1.0,1.0,0.0)\n";
		fid_<<"\t\tcoil.ViewObject.LineWidth = 0.5\n";

		// add to export
		fid_<<"\texport.append(coil)\n";

		// dump into group
		fid_<<"\tif len(group) != 0:\n";
		fid_<<"\t\tgroup[-1].addObject(coil)\n";

		// clear lines
		fid_<<"\tlines = []\n";


		// check if more than one shape
		fid_<<"if len(parts)>1:\n";

		// join together into a fuse
		// this takes more time but hopefully
		// results in a watertight solid
		if(create_union_){
			// perform fuse
			fid_<<"\tfused = parts[0]\n";
			fid_<<"\tfor s in parts[1:]:\n";
			fid_<<"\t\tfused = fused.fuse(s)\n";

			// try simplify
			fid_<<"\ttry:\n";
			fid_<<"\t\tfused = fused.removeSplitter()\n";
			fid_<<"\t\tfused = fused.unifyFaces()\n";
			fid_<<"\texcept Exception:\n";
			fid_<<"\t\tpass\n";
		}

		// join together into a compound object
		// this is much more lightweight
		else{
			fid_<<"\tfused = Part.makeCompound(parts)\n";
		}

		// create feature for holding the shape for the GUI
		fid_<<"\tcoil = doc.addObject('Part::Feature','"<<coil_name<<"')\n";
		fid_<<"\tcoil.Shape = fused\n";

		// single part only becomes a feature
		fid_<<"elif len(parts)==1:\n";
		fid_<<"\tcoil = doc.addObject('Part::Feature','"<<coil_name<<"')\n";
		fid_<<"\tcoil.Shape = parts[0]\n";

		// any type of coil created?
		fid_<<"if len(parts)>0:\n";

		// set view colors etc
		fid_<<"\tif FreeCAD.GuiUp:\n";
		fid_<<"\t\tcoil.ViewObject.LineColor = (1.0,1.0,1.0,0.0)\n";
		fid_<<"\t\tcoil.ViewObject.LineWidth = 0.5\n";
		fid_<<"\t\tcoil.ViewObject.PointColor = (1.0,0.8,0.0,0.0)\n";
		fid_<<"\t\tcoil.ViewObject.PointSize = 4.0\n";
		fid_<<"\t\tcoil.ViewObject.ShapeColor = ("<<color(0)<<","<<color(1)<<","<<color(2)<<",0.0)\n";
		// fid_<<"\t\tcoil.ViewObject.AngularDeflection = 28.5\n";
		// fid_<<"\t\tcoil.ViewObject.Deviation = 2.0\n";

		// add to export list
		fid_<<"\texport.append(coil)\n";

		// dump into group
		fid_<<"\tif len(group) != 0:\n";
		fid_<<"\t\tgroup[-1].addObject(coil)\n";

		// clear part list
		fid_<<"\tparts = []\n";

		// clean features as they are now grouped inside the part
		if(enable_gui_update_)clean_features();

		// done
		fid_<<"\n";
	}

	// save document
	void FreeCAD::save_doc(const boost::filesystem::path &fname){
		fid_<<"# save to native FreeCAD file\n";
		fid_<<"doc.recompute()\n";
		fid_<<"doc.saveAs('"<<fname.generic_string()<<"')\n"; // generic string for python should be fine
		fid_<<"\n";
	}

	// request save
	void FreeCAD::save_step_file(const boost::filesystem::path &fname){
		fid_<<"# save to step file\n";
		fid_<<"doc.recompute()\n";
		fid_<<"Import.export(export,'"<<fname.generic_string()<<"')\n"; // generic string for python should be fine
		fid_<<"\n";
	}

	// write footer to file
	void FreeCAD::write_footer(){
		fid_<<"# setup document for viewing\n";
		fid_<<"doc.UndoMode = 1\n";
		fid_<<"doc.recompute()\n";
		
		fid_<<"# free up storage\n";
		fid_<<"del export\n";

		fid_<<"# setup view\n";
		fid_<<"if FreeCAD.GuiUp:\n";
		fid_<<"\tFreeCADGui.ActiveDocument.ActiveView.fitAll()\n";
		fid_<<"\tFreeCADGui.updateGui()\n";
		fid_<<"else:\n";
		fid_<<"\texit()\n";
		fid_<<"\n";
	}

	// update the gui
	void FreeCAD::trigger_gui_update(){
		fid_<<"# update gui\n";
		fid_<<"if FreeCAD.GuiUp:\n";
		// fid_<<"\tFreeCADGui.ActiveDocument.ActiveView.fitAll()\n";
		fid_<<"\tFreeCADGui.updateGui()\n";
		fid_<<"\n";
	}

	// show object in the GUI by creating a graphical representation
	void FreeCAD::create_feature(const std::string& pyname, const arma::Col<fltp>::fixed<3>& color){
		// check if gui is running
		fid_<<"if FreeCAD.GuiUp:\n";

		// create gui object
		fid_<<"\tgui_"<<pyname<<" = doc.addObject('Part::Feature','"<<pyname<<"')\n";
		fid_<<"\tgui_"<<pyname<<".Shape = "<<pyname<<"\n";

		// trigger recompute
		fid_<<"\tdoc.recompute()\n";

		// set view color and line specs
		fid_<<"\tgui_"<<pyname<<".ViewObject.LineColor = (1.0,1.0,1.0,0.0)\n";
		fid_<<"\tgui_"<<pyname<<".ViewObject.PointColor = (1.0,0.8,0.0,0.0)\n";
		fid_<<"\tgui_"<<pyname<<".ViewObject.PointSize = 4.0\n";
		fid_<<"\tgui_"<<pyname<<".ViewObject.LineWidth = 0.5\n";
		fid_<<"\tgui_"<<pyname<<".ViewObject.ShapeColor = ("<<color(0)<<","<<color(1)<<","<<color(2)<<",0.0)\n";
		// fid_<<"\tgui_"<<pyname<<".ViewObject.AngularDeflection = 28.5\n";
		// fid_<<"\tgui_"<<pyname<<".ViewObject.Deviation = 2.0\n";

		// store in features so that it can be deleted when no longer needed
		fid_<<"\tfeatures.append(gui_"<<pyname<<")\n";
	}

	// clean 
	void FreeCAD::remove_feature(const std::string& pyname){
		// check if gui is running
		fid_<<"if FreeCAD.GuiUp:\n";

		// remove the feature
		fid_<<"\tdoc.removeObject(gui_"<<pyname<<".Name)\n";
	}

	// delete all features that are stored on the list
	// this function should be called when the features
	// are used for the next feature
	void FreeCAD::clean_features(){
		// check if gui is running
		fid_<<"if FreeCAD.GuiUp:\n";

		// check if there are any features
		fid_<<"\tif len(features)>0:\n";

		// walk over feature list and try remove objects
		fid_<<"\t\tfor f in features:\n";
		fid_<<"\t\t\ttry:\n";
		fid_<<"\t\t\t\tdoc.removeObject(f.Name)\n";
		fid_<<"\t\t\texcept Exception:\n";
		fid_<<"\t\t\t\tpass\n";

		// clear the list
		fid_<<"\t\tfeatures = []\n";
	}

	// setup bounding box
	void FreeCAD::setup_bounding_box(
		const arma::field<arma::Mat<fltp> > &x,
		const arma::field<arma::Mat<fltp> > &y, 
		const arma::field<arma::Mat<fltp> > &z){

		// settings
		const arma::Col<fltp>::fixed<3> color = {1,0,0};

		// create bounding box
		const fltp bb_factor = 1.1;
		fltp xmin=arma::Datum<fltp>::inf,ymin=arma::Datum<fltp>::inf,zmin=arma::Datum<fltp>::inf;
		fltp xmax=-arma::Datum<fltp>::inf,ymax=-arma::Datum<fltp>::inf,zmax=-arma::Datum<fltp>::inf;
		for(arma::uword i=0;i<x.n_elem;i++){
			xmin = std::min(xmin, arma::min(arma::vectorise(x(i)))); ymin = std::min(ymin, arma::min(arma::vectorise(y(i)))); zmin = std::min(zmin, arma::min(arma::vectorise(z(i))));
			xmax = std::max(xmax, arma::max(arma::vectorise(x(i)))); ymax = std::max(ymax, arma::max(arma::vectorise(y(i)))); zmax = std::max(zmax, arma::max(arma::vectorise(z(i))));
		}

		// apply factor
		const fltp extra_spacing = RAT_CONST(1e-2)*std::sqrt((xmax - xmin)*(xmax - xmin) + (ymax - ymin)*(ymax - ymin) + (zmax - zmin)*(zmax - zmin));
		xmin = (xmin+xmax)/2 - bb_factor*(xmax-xmin+extra_spacing)/2; ymin = (ymin+ymax)/2 - bb_factor*(ymax-ymin+extra_spacing)/2; zmin = (zmin+zmax)/2 - bb_factor*(zmax-zmin+extra_spacing)/2;
		xmax = (xmin+xmax)/2 + bb_factor*(xmax-xmin+extra_spacing)/2; ymax = (ymin+ymax)/2 + bb_factor*(ymax-ymin+extra_spacing)/2; zmax = (zmin+zmax)/2 + bb_factor*(zmax-zmin+extra_spacing)/2;

		// set view to bounding box
		fid_<<"# show bounding box\n";
		fid_<<"if FreeCAD.GuiUp:\n";
		fid_<<"\tp0 = FreeCAD.Vector("<<scale_*xmin<<", "<<scale_*ymin<<", "<<scale_*zmin<<")\n";
		fid_<<"\tp1 = FreeCAD.Vector("<<scale_*xmax<<", "<<scale_*ymin<<", "<<scale_*zmin<<")\n";
		fid_<<"\tp2 = FreeCAD.Vector("<<scale_*xmax<<", "<<scale_*ymax<<", "<<scale_*zmin<<")\n";
		fid_<<"\tp3 = FreeCAD.Vector("<<scale_*xmin<<", "<<scale_*ymax<<", "<<scale_*zmin<<")\n";

		fid_<<"\tp4 = FreeCAD.Vector("<<scale_*xmin<<", "<<scale_*ymin<<", "<<scale_*zmax<<")\n";
		fid_<<"\tp5 = FreeCAD.Vector("<<scale_*xmax<<", "<<scale_*ymin<<", "<<scale_*zmax<<")\n";
		fid_<<"\tp6 = FreeCAD.Vector("<<scale_*xmax<<", "<<scale_*ymax<<", "<<scale_*zmax<<")\n";
		fid_<<"\tp7 = FreeCAD.Vector("<<scale_*xmin<<", "<<scale_*ymax<<", "<<scale_*zmax<<")\n";

		// create lines
		fid_<<"\tbb0 = Part.LineSegment(p0,p1).toShape()\n";
		fid_<<"\tbb1 = Part.LineSegment(p1,p2).toShape()\n";
		fid_<<"\tbb2 = Part.LineSegment(p2,p3).toShape()\n";
		fid_<<"\tbb3 = Part.LineSegment(p3,p0).toShape()\n";
		fid_<<"\tbb4 = Part.LineSegment(p0,p4).toShape()\n";
		fid_<<"\tbb5 = Part.LineSegment(p1,p5).toShape()\n";
		fid_<<"\tbb6 = Part.LineSegment(p2,p6).toShape()\n";
		fid_<<"\tbb7 = Part.LineSegment(p3,p7).toShape()\n";
		fid_<<"\tbb8 = Part.LineSegment(p4,p5).toShape()\n";
		fid_<<"\tbb9 = Part.LineSegment(p5,p6).toShape()\n";
		fid_<<"\tbb10 = Part.LineSegment(p6,p7).toShape()\n";
		fid_<<"\tbb11 = Part.LineSegment(p7,p4).toShape()\n";
		
		// create line features
		for(arma::uword i=0;i<12;i++)create_feature("bb" + std::to_string(i),color);

		// done
		fid_<<"\n";
	}

