	// method for checking if two edges are ruled surface
	bool FreeCAD::is_ruled_surface(
		const arma::Mat<fltp>& xx, 
		const arma::Mat<fltp>& yy, 
		const arma::Mat<fltp>& zz, 
		const arma::uword idx1, 
		const arma::uword idx2, 
		const rat::fltp tol){

		if(xx.n_cols<=2)return true;

		// get edge lines
		const arma::Mat<fltp> R1 = arma::join_vert(xx.row(idx1), yy.row(idx1), zz.row(idx1));
		const arma::Mat<fltp> R2 = arma::join_vert(xx.row(idx2), yy.row(idx2), zz.row(idx2));
		
		// reconstruct vectors and normalize
		const arma::Mat<fltp> L = Extra::normalize(arma::diff(R1,1,1)); 
		const arma::Mat<fltp> D = Extra::normalize(R2 - R1);

		// take average
		const arma::Mat<fltp> Lav = (L.head_cols(L.n_cols-1) + L.tail_cols(L.n_cols-1))/2;

		// calculate angle of generators
		const arma::Row<fltp> angle = Extra::vec_angle(Lav,D.cols(1,D.n_cols-2));

		// check angles
		return arma::all(arma::abs(angle - arma::Datum<fltp>::pi/2)<tol);
	}

	// is closed
	bool FreeCAD::is_closed(
		const arma::Mat<fltp>& x, 
		const arma::Mat<fltp>& y, 
		const arma::Mat<fltp>& z, 
		const rat::fltp tol){

		// check if start point equals the end point
		return arma::all(arma::abs(x.col(0) - x.col(x.n_cols-1))<tol) && 
			arma::all(arma::abs(y.col(0) - y.col(y.n_cols-1))<tol) && 
			arma::all(arma::abs(z.col(0) - z.col(z.n_cols-1))<tol);
	}

	// get a valid normal vector
	// this does not check for planarity
	arma::Col<fltp>::fixed<3> FreeCAD::get_normal_vector(const arma::Mat<fltp>& R){
		// check input
		assert(!R.empty());
		assert(R.n_rows==3);

		// single point
		if(R.n_cols==1)return {0,0,0};

		// create segments from first to each point
		arma::Mat<fltp> dR = R.each_col() - R.col(0);

		// check if all points the same
		dR.shed_cols(arma::find(Extra::vec_norm(dR)<1e-9));

		// if all points the same they are technically planar 
		// but it is impossible to find a normal vector
		if(dR.empty())return {0,0,0};

		// take cross product between all segments
		const arma::Mat<fltp> V = Extra::cross(arma::repmat(dR.col(0),1,dR.n_cols), dR);

		// calculate length
		const arma::Row<fltp> Vnorm = Extra::vec_norm(V);

		// find longest cross product
		const arma::uword idx = arma::index_max(Vnorm);

		// all points are on a line could not find a single cross valid cross product
		if(Vnorm(idx)<1e-9)return {0,0,0};
		
		// return the selected normal vector
		return Extra::normalize(V.col(idx));
	}

	// planar check
	bool FreeCAD::is_planar(const arma::Mat<fltp>& R, const fltp tol){
		// chekc input
		assert(!R.empty());
		assert(R.n_rows==3);

		// get the normal vector
		const arma::Col<fltp>::fixed<3> N = get_normal_vector(R);

		// all points are on a line could not find a single cross valid cross product
		if(arma::norm(N)<1e-9)return true;

		// get calculate distance to origin in the plane normal direction
		const arma::Row<fltp> w = Extra::dot(arma::repmat(N,1,R.n_cols), R);

		// check if all points lie within the same face normal coordinate
		return arma::all(arma::abs(w - w(0))<tol);
	}

	// check if coordinates form a straight line
	bool FreeCAD::is_straight(const arma::Mat<fltp>&R, const fltp angle_tol){
		// must have at least 2 points to make a straight line
		if(R.n_cols<2)return false;

		// get normal vector
		const arma::Mat<fltp> dR = arma::diff(R,1,1);

		// get curvature 
		const arma::Row<fltp> angle = cmn::Extra::vec_angle(dR.head_cols(dR.n_cols-1),dR.tail_cols(dR.n_cols-1));

		// check for straight line
		return arma::all(arma::abs(angle)<angle_tol);
	}

	// check if coordinates form an arc
	bool FreeCAD::is_arc(const arma::Mat<fltp>&R, const fltp angle_tol){
		// arc must be planar
		if(!is_planar(R))return false;

		// must have at least 3 points to make an Arc
		if(R.n_cols<3)return false;

		// get normal vector
		const arma::Mat<fltp> dR = arma::diff(R,1,1);

		// get curvature 
		const arma::Row<fltp> angle = cmn::Extra::vec_angle(dR.head_cols(dR.n_cols-1),dR.tail_cols(dR.n_cols-1));

		// check for straight line
		if(arma::all(arma::abs(angle)<angle_tol))return false;

		// all the same curvature
		return arma::all(arma::abs(angle - angle(0))<angle_tol);
	}

	// fit circle through first three points
	std::pair<arma::Col<fltp>::fixed<3>, fltp> FreeCAD::fit_circle(const arma::Col<fltp>&R){
		// chekc
		if(R.n_cols<3)rat_throw_line("need at least three points");

		// get the normal vector
		const arma::Col<fltp>::fixed<3> p0 = R.col(0);
		const arma::Col<fltp>::fixed<3> N = get_normal_vector(R.cols(0,2));
		const arma::Col<fltp>::fixed<3> V1 = cmn::Extra::normalize(R.col(1) - R.col(0));
		const arma::Col<fltp>::fixed<3> V2 = cmn::Extra::cross(N,V1);

		// Shift points so p0 -> origin, then project to the (V1,V2) plane
		const arma::Mat<fltp> R0 = R.each_col() - p0;          // 3xN
		const arma::Row<fltp> X  = V1.t() * R0;                // 1xN
		const arma::Row<fltp> Y  = V2.t() * R0;                // 1xN

		// Use the first three points: (0,0), (x2,y2), (x3,y3)
		const fltp x2 = X(1), y2 = Y(1);
		const fltp x3 = X(2), y3 = Y(2);

		const fltp D = fltp(2) * (x2*y3 - y2*x3);

		const fltp r2_2 = x2*x2 + y2*y2;
		const fltp r3_2 = x3*x3 + y3*y3;

		const fltp cx = ( r2_2 * y3 - r3_2 * y2 ) / D;
		const fltp cy = ( r3_2 * x2 - r2_2 * x3 ) / D;

		const arma::Col<fltp>::fixed<3> center = p0 + V1 * cx + V2 * cy;
		const fltp radius = std::sqrt(cx*cx + cy*cy);

		return {center, radius};
	}

